<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';
import {api,state} from '../state';
import {integrationError,errorMessage} from '../api/errors';
import {createSourcePluginsApi,adapterUpdateBody,capabilityStatus,selectablePreviewKeys,validateSubscriptionUrl,type Subscription,type SubscriptionPreview,type RuleResult} from '../api/sourcePlugins';
const sources=createSourcePluginsApi(api),admin=computed(()=>state.user?.role==='admin');
const adapters=ref<any[]>([]),loading=ref(false),error=ref(''),message=ref(''),busy=ref(false),testing=ref<number|null>(null);
const adapter=ref({name:'',kind:'sonovel',base_url:'',enabled:true,secret:''}),editing=ref<any>(null);
const subscriptions=ref<Subscription[]>([]),subscriptionsError=ref(''),subscriptionsLoading=ref(false);
const subscriptionName=ref(''),subscriptionURL=ref(''),preview=ref<SubscriptionPreview|null>(null),previewTarget=ref<Subscription|null>(null),selectedKeys=ref<string[]>([]),previewBusy=ref(false),previewError=ref(''),previewFilter=ref(''),previewPage=ref(1);
const filteredPreview=computed(()=>(preview.value?.sources??[]).filter(s=>!previewFilter.value||s.name.toLowerCase().includes(previewFilter.value.toLowerCase())));
const previewRows=computed(()=>filteredPreview.value.slice((previewPage.value-1)*50,previewPage.value*50));
const rule=ref<{id:number;name:string;text:string;result:RuleResult;reader:string;hosts:string}|null>(null),ruleError=ref(''),ruleBusy=ref(false);
const CHANGE:Record<string,string>={added:'新增',changed:'变化',removed:'移除',unchanged:'无变化'};
async function loadAdapters(){loading.value=true;error.value='';try{adapters.value=(await api.get<any>('/adapters')).items??[]}catch(e){error.value=integrationError('外部书源',e)}finally{loading.value=false}}
async function loadSubscriptions(){subscriptionsLoading.value=true;subscriptionsError.value='';try{subscriptions.value=(await sources.subscriptions()).items??[]}catch(e){subscriptionsError.value=integrationError('书源订阅',e)}finally{subscriptionsLoading.value=false}}
async function createAdapter(){if(busy.value)return;busy.value=true;error.value='';try{await api.post('/adapters',adapter.value);adapter.value={name:'',kind:'sonovel',base_url:'',enabled:true,secret:''};message.value='连接已添加';await loadAdapters()}catch(e){error.value=integrationError('添加连接',e)}finally{busy.value=false}}
async function toggleAdapter(item:any){if(busy.value)return;busy.value=true;error.value='';try{Object.assign(item,await api.send(`/adapters/${item.id}`,'PATCH',{enabled:!item.enabled}));message.value=`「${item.name}」已${item.enabled?'启用':'停用'}`}catch(e){error.value=integrationError('外部书源',e)}finally{busy.value=false}}
function editAdapter(item:any){editing.value={id:item.id,name:item.name,kind:item.kind,base_url:item.base_url,enabled:item.enabled,secret:''}}
async function saveAdapter(){if(!editing.value||busy.value)return;busy.value=true;error.value='';try{await api.send(`/adapters/${editing.value.id}`,'PATCH',adapterUpdateBody(editing.value));editing.value=null;message.value='连接已更新（密钥留空表示保留原密钥）';await loadAdapters()}catch(e){error.value=integrationError('更新连接',e)}finally{busy.value=false}}
async function testAdapter(item:any){testing.value=item.id;error.value='';message.value='';try{const result=await api.post<any>(`/adapters/${item.id}/test`);message.value=`「${item.name}」连接正常 · 版本 ${result.version??'未知'}${result.capabilities?.length?' · 能力：'+result.capabilities.join('、'):''}`}catch(e){error.value=integrationError('连接测试',e)}finally{testing.value=null}}
async function removeAdapter(item:any){if(busy.value)return;busy.value=true;error.value='';try{await api.delete(`/adapters/${item.id}`);adapters.value=adapters.value.filter(x=>x.id!==item.id);message.value='连接已删除'}catch(e){error.value=integrationError('删除连接',e)}finally{busy.value=false}}
function receivePreview(value:SubscriptionPreview,target:Subscription|null){preview.value=value;previewTarget.value=target;selectedKeys.value=selectablePreviewKeys(value.sources);previewFilter.value='';previewPage.value=1}
async function previewSubscription(target:Subscription|null=null){if(previewBusy.value)return;previewError.value='';if(!target){const issue=validateSubscriptionUrl(subscriptionURL.value);if(issue){previewError.value=issue;return}}previewBusy.value=true;preview.value=null;try{receivePreview(target?await sources.previewUpdate(target.id):await sources.preview(subscriptionURL.value.trim()),target)}catch(e){previewError.value=integrationError('订阅预览',e)}finally{previewBusy.value=false}}
async function importPreview(){const value=preview.value;if(!value||busy.value)return;if(!previewTarget.value&&!subscriptionName.value.trim()){previewError.value='请填写订阅名称';return}busy.value=true;previewError.value='';try{const result=previewTarget.value?await sources.updateSubscription(previewTarget.value.id,selectedKeys.value,value.revision):await sources.importSubscription(subscriptionName.value.trim(),value.url,selectedKeys.value,value.revision);message.value=`订阅已${previewTarget.value?'更新':'导入'}：新增 ${result.added}、变化 ${result.changed}、移除 ${result.removed}，共 ${result.source_count} 个书源`;preview.value=null;previewTarget.value=null;await Promise.all([loadAdapters(),loadSubscriptions()])}catch(e){previewError.value=integrationError('应用订阅',e)}finally{busy.value=false}}
async function openRule(item:any){ruleError.value='';ruleBusy.value=true;try{const result=await sources.rule(item.id);rule.value={id:item.id,name:item.name,text:JSON.stringify(result.source,null,2),result,reader:result.reader_adapter_id?String(result.reader_adapter_id):'0',hosts:(result.allowed_hosts??[]).join(', ')}}catch(e){ruleError.value=integrationError('读取书源规则',e)}finally{ruleBusy.value=false}}
async function saveRule(){if(!rule.value||ruleBusy.value)return;let source:unknown;try{source=JSON.parse(rule.value.text)}catch(e){ruleError.value='规则 JSON 格式错误：'+errorMessage(e);return}ruleError.value='';ruleBusy.value=true;try{const draft=rule.value;draft.result=await sources.saveRule(draft.id,{source,...(draft.reader?{reader_adapter_id:Number(draft.reader)}:{}),...(draft.hosts.trim()?{allowed_hosts:draft.hosts.split(/[\s,，]+/).filter(Boolean)}:{})});draft.text=JSON.stringify(draft.result.source,null,2);message.value='规则已保存，兼容性报告已刷新';await loadAdapters()}catch(e){ruleError.value=integrationError('保存规则',e)}finally{ruleBusy.value=false}}
async function rollbackRule(){if(!rule.value||ruleBusy.value)return;ruleBusy.value=true;ruleError.value='';try{rule.value.result=await sources.rollbackRule(rule.value.id);rule.value.text=JSON.stringify(rule.value.result.source,null,2);message.value='已恢复上一版规则';await loadAdapters()}catch(e){ruleError.value=integrationError('回滚规则',e)}finally{ruleBusy.value=false}}
watch(subscriptionURL,()=>{if(preview.value&&!previewTarget.value)preview.value=null});watch(previewFilter,()=>{previewPage.value=1});
onMounted(()=>{if(admin.value)void Promise.all([loadAdapters(),loadSubscriptions()])});
</script>
<template>
<section v-if="admin" class="panel source-plugins" id="external-sources" aria-label="外部书源配置">
<h2>我的外部书源</h2><p>订阅你选择的书源，或连接自己的 SoNovel / reader 服务。家庭成员可使用已启用、兼容的书源搜索并加入公共书库。</p>
<RouterLink class="button" to="/discover">搜索在线书源</RouterLink>
<p v-if="message" role="status" class="status-banner">{{message}}</p><p v-if="error" role="alert" class="error">{{error}} <button @click="loadAdapters">重试</button></p>
<section aria-label="书源订阅"><h3>书源订阅</h3><p>粘贴订阅地址后点击预览。定义兼容表示规则可解析，实际搜索、登录或网站限制需另行验证。</p>
<form @submit.prevent="previewSubscription()"><label>订阅名称<input v-model="subscriptionName" placeholder="例如：我的小说书源" maxlength="80"></label><label>订阅 URL<input v-model="subscriptionURL" type="url" required placeholder="https://example.org/sources.json"></label><button :disabled="previewBusy||busy">{{previewBusy?'正在预览…':'预览订阅'}}</button></form>
<p v-if="subscriptionsLoading" role="status">正在读取订阅…</p><p v-else-if="subscriptionsError" role="alert" class="error">{{subscriptionsError}} <button @click="loadSubscriptions">重试</button></p><p v-else-if="!subscriptions.length" class="muted">尚未添加订阅。</p>
<article v-for="item in subscriptions" :key="item.id" class="source-row"><div><strong>{{item.name}}</strong><p class="url">{{item.url}}</p><small>{{item.source_count}} 个书源 · {{item.updated_at?new Date(item.updated_at).toLocaleString():'尚未更新'}}</small></div><button :disabled="previewBusy||busy" @click="previewSubscription(item)">检查更新</button></article>
<p v-if="previewError" role="alert" class="error">{{previewError}}</p>
<section v-if="preview" class="preview" aria-label="订阅预览"><h3>{{previewTarget?'更新「'+previewTarget.name+'」':'订阅预览'}} · {{preview.total}} 个定义</h3><p class="url">{{preview.url}}</p><p>选择要加入插件库的书源，导入后默认停用。暂不支持的定义也可导入，再编辑规则或配置 reader。更新时请检查移除项。</p><div class="row-actions"><button type="button" @click="selectedKeys=selectablePreviewKeys(preview.sources)">选择全部兼容书源</button><button type="button" @click="selectedKeys=[]">清空选择</button><small>已选 {{selectedKeys.length}} 项</small></div><label>筛选预览书源<input v-model="previewFilter" placeholder="按名称筛选"></label>
<article v-for="source in previewRows" :key="source.key" class="preview-row"><label class="inline"><input v-model="selectedKeys" type="checkbox" :value="source.key" :disabled="source.change==='removed'"><strong>{{source.name}}</strong></label><span class="badge">{{CHANGE[source.change]}}</span><p :class="{error:!source.supported}">{{source.supported?'定义兼容 · 尚未实测':'当前定义不支持 · 可导入后修正规则'}}<template v-if="source.capabilities?.length"> · {{source.capabilities.join('、')}}</template></p><p v-if="source.local_edit||source.conflict" class="issue">{{source.conflict?'上游与本地修改有差异，订阅更新保留本地规则；请在规则编辑器对比。':'含本地修改，订阅更新保留本地规则。'}}</p><p v-for="issue in source.issues" :key="issue" class="issue">{{issue}}</p></article>
<div v-if="filteredPreview.length>50" class="row-actions"><button :disabled="previewPage===1" @click="previewPage--">上一页</button><span>{{previewPage}} / {{Math.ceil(filteredPreview.length/50)}}</span><button :disabled="previewPage*50>=filteredPreview.length" @click="previewPage++">下一页</button></div>
<div class="row-actions"><button class="primary" :disabled="busy||(!previewTarget&&!selectedKeys.length)" @click="importPreview">{{busy?'正在应用…':previewTarget?'应用订阅更新':'导入所选书源'}}</button><button :disabled="busy" @click="preview=null;previewTarget=null">取消预览</button></div></section>
</section>
<section aria-label="外部服务连接"><h3>服务连接</h3><form @submit.prevent="createAdapter"><label>名称<input v-model="adapter.name" required></label><label>类型<select v-model="adapter.kind"><option value="sonovel">sonovel</option><option value="reader">reader</option></select></label><label>服务地址<input v-model="adapter.base_url" type="url" required placeholder="http://192.168.1.10:8080"></label><label>访问密钥<input v-model="adapter.secret" type="password" autocomplete="off" placeholder="可选"></label><label class="inline"><input v-model="adapter.enabled" type="checkbox">立即启用</label><button :disabled="busy">添加连接</button></form>
<p v-if="loading" role="status">正在读取连接…</p><p v-else-if="!adapters.length&&!error">还没有外部书源。</p>
<article v-for="item in adapters" :key="item.id" class="source-row"><div><strong>{{item.name}}</strong><p>{{item.kind==='legado'?'订阅书源':item.kind}} · {{item.enabled?'已启用':'已停用'}}<template v-if="item.kind!=='legado'"> · {{item.has_secret?'已配置密钥':'未配置密钥'}}</template><template v-if="item.version"> · 规则版本 {{item.version}}</template></p><p class="url" v-if="item.base_url">{{item.base_url}}</p><small>{{capabilityStatus(item)}}<template v-if="item.capabilities?.length"> · {{item.capabilities.join('、')}}</template></small><p v-for="issue in item.issues" :key="issue" class="issue">{{issue}}</p></div><div class="row-actions"><button :disabled="busy||item.supported===false&&!item.enabled" @click="toggleAdapter(item)">{{item.enabled?'停用':'启用'}}</button><button v-if="item.kind!=='legado'" :disabled="busy" @click="editAdapter(item)">编辑</button><button v-else :disabled="ruleBusy" @click="openRule(item)">编辑规则</button><button :disabled="testing!==null||item.supported===false" @click="testAdapter(item)">{{testing===item.id?'测试中…':'测试连接'}}</button><button :disabled="busy" @click="removeAdapter(item)">删除</button></div></article>
<form v-if="editing" class="edit-form" @submit.prevent="saveAdapter"><h3>编辑「{{editing.name}}」</h3><label>名称<input v-model="editing.name" required></label><label>类型<select v-model="editing.kind"><option value="sonovel">sonovel</option><option value="reader">reader</option></select></label><label>服务地址<input v-model="editing.base_url" type="url" required></label><label>访问密钥（留空保留原密钥）<input v-model="editing.secret" type="password" autocomplete="off" placeholder="留空保留原密钥"></label><label class="inline"><input v-model="editing.enabled" type="checkbox">启用</label><div class="row-actions"><button class="primary" :disabled="busy">保存修改</button><button type="button" :disabled="busy" @click="editing=null">取消</button></div></form>
<p v-if="ruleError" role="alert" class="error">{{ruleError}}</p><form v-if="rule" class="rule-editor" @submit.prevent="saveRule"><h3>编辑规则「{{rule.name}}」 · 版本 {{rule.result.version}}</h3><p v-if="rule.result.local_edit" role="status" class="status-banner">当前含本地修改，订阅更新保留本地规则。请对照上游内容后手动修改。</p><p v-if="rule.result.removed" class="issue">上游已移除此定义，当前规则仍保留；请检查执行状态。</p><label>书源规则 JSON<textarea v-model="rule.text" rows="12" spellcheck="false"></textarea></label><details v-if="rule.result.upstream_source!==undefined" class="upstream-rule"><summary>查看上游规则并对比</summary><p>以下是订阅中的上游版本，只读显示。</p><pre>{{JSON.stringify(rule.result.upstream_source,null,2)}}</pre></details><details><summary>高级配置</summary><label>使用 reader 执行规则<select v-model="rule.reader"><option value="0">Go 原生执行</option><option v-for="reader in adapters.filter(x=>x.kind==='reader')" :key="reader.id" :value="String(reader.id)" :disabled="reader.enabled===false">{{reader.name}}{{reader.enabled===false?'（已停用）':''}}</option></select></label><label>允许访问的域名<input v-model="rule.hosts" placeholder="留空保留；多个域名用逗号分隔"></label></details><p>{{rule.result.report?.supported?'定义兼容 · 尚未实测':'请检查兼容性报告'}}</p><p v-for="issue in rule.result.report?.issues" :key="issue" class="issue">{{issue}}</p><div class="row-actions"><button class="primary" :disabled="ruleBusy">保存规则</button><button type="button" :disabled="ruleBusy" @click="rollbackRule">恢复上一版</button><button type="button" :disabled="ruleBusy" @click="rule=null;ruleError=''">关闭</button></div></form>
</section>
</section><section v-else class="panel"><h2>外部书源</h2><p>书源配置由管理员维护，你可以使用已启用的书源搜索和导入。</p><RouterLink class="button primary" to="/discover">搜索在线书源</RouterLink></section>
</template>
<style scoped>
.source-plugins>section{border-top:1px solid var(--border);margin-top:24px;padding-top:12px}.source-plugins form{max-width:650px}.source-row{display:flex;justify-content:space-between;gap:14px;padding:14px 0;border-top:1px solid var(--border)}.source-row>div:first-child{min-width:0}.source-row p{margin:6px 0}.source-row .row-actions{align-self:center;flex-wrap:wrap;justify-content:flex-end;flex-shrink:0}.url{overflow-wrap:anywhere;color:var(--muted);font-size:13px}.issue{font-size:13px;color:#8a551e;overflow-wrap:anywhere}.inline{display:flex;align-items:center;gap:8px}.inline input{width:20px;height:20px;flex:none}.preview{border:1px solid var(--border);border-radius:12px;padding:16px;margin:16px 0}.preview-row{border-top:1px solid var(--border);padding:12px 0;overflow-wrap:anywhere}.preview-row p{margin:6px 0}.badge{display:inline-block;padding:3px 8px;background:#e5eeea;border-radius:8px;font-size:12px}.rule-editor textarea{font-family:monospace;font-size:13px;min-height:220px}.rule-editor{border-top:1px solid var(--border);padding-top:12px}.source-plugins details{margin:12px 0}.upstream-rule pre{white-space:pre-wrap;overflow-wrap:anywhere;max-width:100%;padding:12px;background:var(--surface-2);border-radius:8px;font-size:13px}.edit-form{margin-top:20px}@media(max-width:650px){.source-row{display:block}.source-row .row-actions{justify-content:flex-start;margin-top:10px}.source-plugins .row-actions{flex-wrap:wrap}.preview{padding:12px}.source-plugins button{min-height:44px}}
</style>
